{{ config(
            materialized='table',
                post_hook={
                    "sql": "--create or replace table snitch_db.maplemonk.sku_live_mech_v2 as WITH data AS ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' THEN UPPER(TRIM(sku)) ELSE sku_group END AS sku_group, from_party AS vendor_name, SUM( CASE WHEN transfer_branch_code != 32 THEN total_qty ELSE NULL END ) AS ordered, SUM( CASE WHEN transfer_branch_code = 8 THEN total_qty ELSE NULL END ) AS south, SUM( CASE WHEN transfer_branch_code = 94 THEN total_qty ELSE NULL END ) AS north FROM SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER GROUP BY 1, 2 -- IMPORTANT: added vendor_name ), puta AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) ELSE UPPER(TRIM(REGEXP_REPLACE(\"Item Type skuCode\"::STRING, \'-[^-]+$\', \'\'))) END AS sku_group, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_completed_quantity ELSE NULL END ) AS south, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_completed_quantity ELSE NULL END ) AS north, SUM( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_completed_quantity ELSE NULL END ) AS inwarded, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_updated::date ELSE NULL END ) AS south_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_updated::date ELSE NULL END ) AS north_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_updated::date ELSE NULL END ) AS inwarded_date FROM snitch_db.maplemonk.putaway_tracking WHERE final_type = \'New Inward\' GROUP BY 1 ), final AS ( SELECT sku_group, d.ordered, d.vendor_name, d.south South_PO, d.north North_PO, p.inwarded, p.south south_inwarded, p.north North_inwarded, p.north_inwarded_date north_inwarded_date, p.south_inwarded_date south_inwarded_date, p.inwarded_date inwarded_date, b.final_live_date, (p.inwarded / NULLIF(d.ordered, 0)) inwarded_prec, ( CASE WHEN d.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN d.north > 0 THEN 1 ELSE 0 END ) AS PO_raised_WH_count, ( CASE WHEN p.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN p.north > 0 THEN 1 ELSE 0 END ) AS inwarded_WH_count, CASE WHEN c.sku_group IS NULL THEN \'No Offline Allocation\' ELSE \'Offline Allocated\' END Offline_Allocated_Status FROM data d LEFT JOIN puta p USING (sku_group) LEFT JOIN snitch_db.maplemonk.product_journey b USING (sku_group) LEFT JOIN ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' THEN UPPER(TRIM(sku)) ELSE REGEXP_REPLACE(sku, \'-[^-]+$\', \'\') END AS sku_group FROM snitch_db.maplemonk.b2b_journey ) c USING (sku_group) WHERE sku_group NOT IN ( SELECT DISTINCT sku_group FROM snitch_db.maplemonk.horizontal_sales_categories WHERE sku_group IS NOT NULL and type =\'Shopify\' ) AND ordered >= 100 ), live_check as ( select distinct sku_group, live_date from snitch_db.maplemonk.category_journey ), north_ranked AS ( SELECT t2.*, /* parse planned_date into a real DATE for ordering */ COALESCE( TRY_TO_DATE(t2.planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD MON YYYY\'), TRY_TO_DATE(t2.planned_date) ) AS planned_dt_parsed, ROW_NUMBER() OVER ( PARTITION BY t2.sku_no ORDER BY COALESCE( TRY_TO_DATE(t2.planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD MON YYYY\'), TRY_TO_DATE(t2.planned_date) ) DESC NULLS LAST ) AS rn FROM snitch_db.maplemonk.inward_details_sku_level t2 ), north AS ( SELECT * FROM north_ranked WHERE rn = 1 ), south_ranked AS ( SELECT t3.*, COALESCE( TRY_TO_DATE(t3.planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD MON YYYY\'), TRY_TO_DATE(t3.planned_date) ) AS planned_dt_parsed, ROW_NUMBER() OVER ( PARTITION BY t3.sku_no ORDER BY COALESCE( TRY_TO_DATE(t3.planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD MON YYYY\'), TRY_TO_DATE(t3.planned_date) ) DESC NULLS LAST ) AS rn FROM snitch_db.maplemonk.SOUTH_INWARD_DETAILS_SKU_LEVEL t3 ), south AS ( SELECT * FROM south_ranked WHERE rn = 1 ) SELECT distinct f.sku_group, f.ordered, f.vendor_name, f.South_PO, f.North_PO, f.inwarded, f.south_inwarded, f.North_inwarded, f.PO_raised_WH_count, f.inwarded_WH_count, ROUND(100 * f.inwarded_prec, 1) AS inwarded_prec, CASE WHEN f.inwarded_prec >= 0.75 THEN f.inwarded_date END AS WH_Live_date, cj.image_url AS SKU_image, CASE WHEN f.sku_group LIKE \'MP%\' THEN \'Marketplace Specific SKU\' WHEN f.inwarded_prec >= 0.75 THEN \'Ready to go live\' WHEN INWARDED_WH_COUNT = 2 THEN \'Ready to go live\' WHEN f.PO_raised_WH_count < f.inwarded_WH_count THEN \'Ready to go live\' ELSE \'Not Ready to go Live\' END AS Remarks, f.Offline_Allocated_Status, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.75 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT > INWARDED_WH_COUNT or INWARDED_WH_COUNT <= 1 ) AND f.final_live_date IS NOT NULL THEN \'Should not have made Live\' WHEN f.inwarded_prec >= 0.75 AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT ) AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN INWARDED_WH_COUNT = 2 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.PO_Raised_WH_COUNT < INWARDED_WH_COUNT AND f.final_live_date IS NULL THEN \'Make it Live in Online\' ELSE \'Do not Make Live\' END END AS Online_Remarks, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.75 AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN f.inwarded_prec < 0.75 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Should not have made Allocations\' WHEN f.inwarded_prec >= 0.75 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' ELSE \'Do not Make Allocations\' END END AS Offline_Remarks, lf.live_date, CASE WHEN REGEXP_LIKE(north.planned_date, \'^[0-9]{2}-[A-Za-z]{3}-[0-9]{4}$\') THEN TO_CHAR(TO_DATE(north.planned_date, \'DD-MON-YYYY\'), \'DD/MM/YYYY\') ELSE north.planned_date END AS north_planned_date, north.actual_delivered_date AS north_actual_delivered_date, south.planned_date AS south_planned_date, /* SOUTH actual delivered -> DD/MM/YYYY */ CASE WHEN REGEXP_LIKE(south.actual_delivered_date,\'^[0-9]{1,2}-[A-Za-z]{3}-[0-9]{4}$\') THEN TO_CHAR(TO_DATE(south.actual_delivered_date,\'DD-MON-YYYY\'),\'DD/MM/YYYY\') WHEN REGEXP_LIKE(south.actual_delivered_date,\'^[0-9]{1,2} [A-Za-z]{3} [0-9]{4}$\') THEN TO_CHAR(TO_DATE(south.actual_delivered_date,\'DD MON YYYY\'),\'DD/MM/YYYY\') WHEN REGEXP_LIKE(south.actual_delivered_date,\'^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$\') THEN TO_CHAR(TO_DATE(south.actual_delivered_date,\'DD/MM/YYYY\'),\'DD/MM/YYYY\') ELSE NULL END AS south_actual_delivered_date, DATEDIFF( \'DAY\', TRY_TO_DATE(north_planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(north_actual_delivered_date, \'DD/MM/YYYY\') ) AS DIFF_NORTH_RECIEVED, DATEDIFF( \'DAY\', TRY_TO_DATE(south_planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(south_actual_delivered_date, \'DD/MM/YYYY\') ) AS DIFF_SOUTH_RECIEVED FROM final f LEFT JOIN north ON north.sku_no = sku_group LEFT JOIN south ON south.sku_no = sku_group LEFT JOIN snitch_db.maplemonk.category_journey cj ON cj.sku_group = f.sku_group left join live_check lf on f.sku_group = lf.sku_group where lf.live_date > \'2026-01-01\' or lf.live_date is null;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            